window.bookSummaryJSON = "<p>Ezekiel Summers, the son of a preacher, lost an eye because of me.<br> <br> Cyrus Porter, the child of a sociopath, burned a man for touching me.<br> <br> Levinston Cartwright, an heir to billions, used his wealth to stalk me.<br> <br> Three vastly different, yet dangerous men with one thing in common…<br> <br> An obsession with me.<br> <br> *Feral is a Standalone*</p>"; 
